54	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
55	     * API's read-only {@code initials} field.
56	     *
57	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
58	     * applied only where referenced via {@code qualifiedByName}.
59	     */
60	    @Named("formatInitials")
61	    default String formatInitials(Owner owner) {
62	        if (owner == null) {
63	            return null;
64	        }
65	        return initial(owner.getFirstName()) + initial(owner.getLastName());
66	    }
